class Trie {

  class TrieNode {
    TrieNode[] alphabets;
    boolean isEnd;
    int wordsEnding;
    int prefix;

    public TrieNode() {
      alphabets = new TrieNode[26];
      isEnd = false;
      wordsEnding = 0;
      prefix = 0;
    }
  }

  TrieNode root;

  public Trie() {
    root = new TrieNode();
  }

  public void insert(String word) {
    TrieNode curr = root;
    for (char c : word.toCharArray()) {
      int idx = c - 'a';

      if (curr.alphabets[idx] == null) curr.alphabets[idx] = new TrieNode();
      curr = curr.alphabets[idx];
      curr.prefix++;
    }
    curr.wordsEnding++;
    curr.isEnd = true;
  }

  public int countWordsEqualTo(String word) {
    TrieNode curr = root;
    for (char c : word.toCharArray()) {
      int idx = c - 'a';
      if (curr.alphabets[idx] == null) return 0;
      curr = curr.alphabets[idx];
    }
    return curr.wordsEnding;
  }

  public int countWordsStartingWith(String prefix) {
    TrieNode curr = root;
    for (char c : prefix.toCharArray()) {
      int idx = c - 'a';
      if (curr.alphabets[idx] == null) return 0;
      curr = curr.alphabets[idx];
    }
    return curr.prefix;
  }

  public void erase(String word) {
    TrieNode curr = root;
    for (char c : word.toCharArray()) {
      int idx = c - 'a';
      curr = curr.alphabets[idx];
      curr.prefix--;
    }
    curr.wordsEnding--;
  }
}

